create unique index versions_goal_number on kaika_workshop.versions(workspace_id,goal_id,version_no); create unique index versions_goal_identity on kaika_workshop.versions(workspace_id,goal_id,id); create unique index approvals_one_per_version on kaika_workshop.approvals(workspace_id,version_id); alter table kaika_workshop.goals add constraint active_version_belongs_to_goal foreign key(workspace_id,id,active_version_id) references kaika_workshop.versions(workspace_id,goal_id,id) deferrable initially deferred; create unique index checkpoints_delivery_identity on kaika_workshop.checkpoints(workspace_id,id,deliverable_id); alter table kaika_workshop.evidence add constraint evidence_checkpoint_belongs_to_delivery foreign key(workspace_id,checkpoint_id,deliverable_id) references kaika_workshop.checkpoints(workspace_id,id,deliverable_id) deferrable initially deferred; alter table kaika_workshop.acceptances add constraint acceptance_checkpoint_belongs_to_delivery foreign key(workspace_id,checkpoint_id,deliverable_id) references kaika_workshop.checkpoints(workspace_id,id,deliverable_id) deferrable initially deferred;
